/// A `ProtocolError`'s variant name and its zero-based position in the
/// definition. Exhaustive with no fallback arm: a variant added to the Rust
/// enum and not to the definition, or the other way round, fails to compile.
pub fn protocol_error_variant(e: &crate::ProtocolError) -> (&'static str, i32) {
    match e {
        crate::ProtocolError::NotStarted { .. } => ("NotStarted", 0),
        crate::ProtocolError::AlreadyStarted { .. } => ("AlreadyStarted", 1),
        crate::ProtocolError::InvalidConfiguration { .. } => ("InvalidConfiguration", 2),
        crate::ProtocolError::SendFailed { .. } => ("SendFailed", 3),
        crate::ProtocolError::NoKeyPackage { .. } => ("NoKeyPackage", 4),
        crate::ProtocolError::SessionNotReady { .. } => ("SessionNotReady", 5),
        crate::ProtocolError::EncryptFailed { .. } => ("EncryptFailed", 6),
        crate::ProtocolError::InvalidState { .. } => ("InvalidState", 7),
        crate::ProtocolError::MlsNotInitialized { .. } => ("MlsNotInitialized", 8),
        crate::ProtocolError::MlsError { .. } => ("MlsError", 9),
        crate::ProtocolError::UserBlocked { .. } => ("UserBlocked", 10),
        crate::ProtocolError::MediaTransferLimit { .. } => ("MediaTransferLimit", 11),
        crate::ProtocolError::LockPoisoned { .. } => ("LockPoisoned", 12),
        crate::ProtocolError::Other { .. } => ("Other", 13),
        crate::ProtocolError::TransportError { .. } => ("TransportError", 14),
        crate::ProtocolError::SerializationError { .. } => ("SerializationError", 15),
        crate::ProtocolError::ServiceError { .. } => ("ServiceError", 16),
        crate::ProtocolError::GroupNotFound { .. } => ("GroupNotFound", 17),
        crate::ProtocolError::PermissionDenied { .. } => ("PermissionDenied", 18),
        crate::ProtocolError::InvalidArgument { .. } => ("InvalidArgument", 19),
        crate::ProtocolError::DataDisabled { .. } => ("DataDisabled", 20),
        crate::ProtocolError::DataStorageUnavailable { .. } => ("DataStorageUnavailable", 21),
        crate::ProtocolError::DocTooLarge { .. } => ("DocTooLarge", 22),
        crate::ProtocolError::DataCorrupted { .. } => ("DataCorrupted", 23),
        crate::ProtocolError::TelemetryConfigInvalid { .. } => ("TelemetryConfigInvalid", 24),
    }
}

